 "content": "def transform(grid):
    """Shear every colored cell left by its distance above the object's bottom row."""
    h, w = len(grid), len(grid[0])
    colored_rows = [r for r, row in enumerate(grid) if any(v != 0 for v in row)]
    if not colored_rows:
        return [row[:] for row in grid]
    bottom = max(colored_rows)
    out = [[0] * w for _ in range(h)]
    for r, row in enumerate(grid):
        shift = r - bottom
        for c, value in enumerate(row):
            if value != 0:
                nc = c + shift
                if 0 <= nc < w:
                    out[r][nc] = value
    return out
